#include <iostream>
#include <string>

class PooledConnection {
public:
    explicit PooledConnection(int id) : id_(id), inUse_(false) {}

    void reset() {
        // clear any leftover query state before returning to the pool
        lastQuery_.clear();
    }

    std::string query(const std::string& sql) {
        lastQuery_ = sql;
        return "result for [" + sql + "] on connection " + std::to_string(id_);
    }

    int getId() const { return id_; }

private:
    int id_;
    bool inUse_;
    std::string lastQuery_;
};

int main() {
    PooledConnection conn(1);
    std::cout << conn.query("SELECT * FROM orders WHERE id = 42") << std::endl;
    conn.reset();
    std::cout << "connection " << conn.getId() << " reset and ready for reuse" << std::endl;
    return 0;
}

