class ConnectionPool {
  constructor(maxSize) {
    this.maxSize = maxSize;
    this.available = [];
    this.inUse = new Set();
    this.nextId = 1;
  }

  acquire() {
    let conn;
    if (this.available.length > 0) {
      conn = this.available.pop();
    } else if (this.inUse.size < this.maxSize) {
      conn = new PooledConnection(this.nextId++);
    } else {
      throw new Error('pool exhausted: all connections in use');
    }
    conn.inUse = true;
    this.inUse.add(conn);
    return conn;
  }

  release(conn) {
    if (!this.inUse.has(conn)) return;
    conn.reset();
    conn.inUse = false;
    this.inUse.delete(conn);
    this.available.push(conn);
  }

  stats() {
    return { available: this.available.length, inUse: this.inUse.size };
  }
}

