import java.util.*;

class PooledConnection {
    private final int id;
    private boolean inUse;
    private String lastQuery;

    public PooledConnection(int id) {
        this.id = id;
    }

    public void reset() {
        this.lastQuery = null;
    }

    public String query(String sql) {
        this.lastQuery = sql;
        return "result for [" + sql + "] on connection " + id;
    }

    public int getId() {
        return id;
    }
}

class ConnectionPool {
    private final int maxSize;
    private final Deque<PooledConnection> available = new ArrayDeque<>();
    private final Set<PooledConnection> inUse = new HashSet<>();
    private int nextId = 1;

    public ConnectionPool(int maxSize) {
        this.maxSize = maxSize;
    }

    public synchronized PooledConnection acquire() {
        PooledConnection conn;
        if (!available.isEmpty()) {
            conn = available.pop();
        } else if (inUse.size() < maxSize) {
            conn = new PooledConnection(nextId++);
        } else {
            throw new IllegalStateException("pool exhausted: all connections in use");
        }
        inUse.add(conn);
        return conn;
    }

    public synchronized void release(PooledConnection conn) {
        if (!inUse.remove(conn)) return;
        conn.reset();
        available.push(conn);
    }

    public synchronized Map<String, Integer> stats() {
        Map<String, Integer> s = new HashMap<>();
        s.put("available", available.size());
        s.put("inUse", inUse.size());
        return s;
    }
}

public class Main {
    public static void main(String[] args) {
        ConnectionPool pool = new ConnectionPool(2);
        PooledConnection first = pool.acquire();
        PooledConnection second = pool.acquire();
        System.out.println("acquired two: " + pool.stats());
        pool.release(first);
        System.out.println("released one: " + pool.stats());
        PooledConnection third = pool.acquire();
        System.out.println("acquired again: " + pool.stats());
    }
}

