#include <iostream>
#include <string>
#include <deque>
#include <unordered_set>
#include <stdexcept>
#include <memory>

class PooledConnection {
public:
    explicit PooledConnection(int id) : id_(id), inUse_(false) {}

    void reset() {
        lastQuery_.clear();
    }

    std::string query(const std::string& sql) {
        lastQuery_ = sql;
        return "result for [" + sql + "] on connection " + std::to_string(id_);
    }

    int getId() const { return id_; }

private:
    int id_;
    bool inUse_;
    std::string lastQuery_;
};

class ConnectionPool {
public:
    explicit ConnectionPool(int maxSize) : maxSize_(maxSize), nextId_(1) {}

    std::shared_ptr<PooledConnection> acquire() {
        std::shared_ptr<PooledConnection> conn;
        if (!available_.empty()) {
            conn = available_.back();
            available_.pop_back();
        } else if (static_cast<int>(inUse_.size()) < maxSize_) {
            conn = std::make_shared<PooledConnection>(nextId_++);
        } else {
            throw std::runtime_error("pool exhausted: all connections in use");
        }
        inUse_.insert(conn);
        return conn;
    }

    void release(const std::shared_ptr<PooledConnection>& conn) {
        if (inUse_.erase(conn) == 0) return;
        conn->reset();
        available_.push_back(conn);
    }

    void printStats() const {
        std::cout << "available=" << available_.size() << " inUse=" << inUse_.size();
    }

private:
    int maxSize_;
    int nextId_;
    std::deque<std::shared_ptr<PooledConnection>> available_;
    std::unordered_set<std::shared_ptr<PooledConnection>> inUse_;
};

int main() {
    ConnectionPool pool(2);
    auto first = pool.acquire();
    auto second = pool.acquire();
    std::cout << "acquired two: ";
    pool.printStats();
    std::cout << std::endl;

    pool.release(first);
    std::cout << "released one: ";
    pool.printStats();
    std::cout << std::endl;

    auto third = pool.acquire();
    std::cout << "acquired again: ";
    pool.printStats();
    std::cout << std::endl;
    return 0;
}

